from collections import deque
R=C=16
vis=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]!=7 and (r,c) not in vis:
   q=[(r,c)];vis.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b]!=7 and (a,b) not in vis:
      vis.add((a,b));q.append((a,b))
   colors=sorted({grid[x][y] for x,y in cells if grid[x][y]!=0})
   bounds=(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells))
   comps.append((len(cells),bounds,colors,cells))
[(n,b,co) for n,b,co,_ in comps]

target={2,5,8}
remove=[]
for n,b,co,cells in comps:
 if target.issubset(set(co)) and not (b[0]==0 and b[2]==0):
  remove.append((n,b,co,cells))
[(n,b,co) for n,b,co,_ in remove]
